#include <Arduino.h>
#include <TM1637Display.h>
#include <DHT.h>
#include <math.h>
#include <string.h>

TM1637Display display(4, 5);
DHT dht(7, DHT11);
enum Mode { TEMP_MODE, HUMI_MODE, BOTH_MODE };
Mode mode = TEMP_MODE;
bool serialEnabled = true;
bool showHumidity = false;
float temperatureValue = NAN, humidityValue = NAN;
unsigned long lastSensor = 0, lastReport = 0, lastAlternate = 0;
unsigned long lastByte = 0, buttonChanged = 0;
bool sensorStarted = false;
int rawButton = HIGH, stableButton = HIGH;
char command[24];
unsigned int commandLength = 0;

void acceptCommand() {
  command[commandLength] = '\0';
  if (strcmp(command, "TEMP") == 0) mode = TEMP_MODE;
  else if (strcmp(command, "HUMI") == 0) mode = HUMI_MODE;
  else if (strcmp(command, "BOTH") == 0) {
    mode = BOTH_MODE;
    showHumidity = false;
    lastAlternate = millis();
  }
  commandLength = 0;
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  Serial.begin(9600);
  dht.begin();
  display.setBrightness(5);
  Serial.println("TEMP / HUMI / BOTH");
}

void loop() {
  unsigned long now = millis();
  while (Serial.available() > 0) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') {
      if (commandLength) acceptCommand();
    } else if (commandLength < sizeof(command) - 1) {
      command[commandLength++] = c;
    }
  }
  now = millis();
  if (commandLength && now - lastByte >= 20) acceptCommand();

  int reading = digitalRead(2);
  if (reading != rawButton) {
    rawButton = reading;
    buttonChanged = now;
  }
  if (now - buttonChanged >= 40 && stableButton != rawButton) {
    stableButton = rawButton;
    if (stableButton == LOW) serialEnabled = !serialEnabled;
  }

  if (!sensorStarted || now - lastSensor >= 2000) {
    sensorStarted = true;
    lastSensor = now;
    float t = dht.readTemperature();
    float h = dht.readHumidity();
    if (!isnan(t)) temperatureValue = t;
    if (!isnan(h)) humidityValue = h;
  }
  if (mode == BOTH_MODE && now - lastAlternate >= 2000) {
    lastAlternate = now;
    showHumidity = !showHumidity;
  }
  bool useHumidity = mode == HUMI_MODE || (mode == BOTH_MODE && showHumidity);
  float value = useHumidity ? humidityValue : temperatureValue;
  if (!isnan(value)) display.showNumberDec((int)round(value), false);

  if (serialEnabled && now - lastReport >= 1000) {
    lastReport = now;
    Serial.print("TEMP: ");
    Serial.print(temperatureValue);
    Serial.print(" HUMI: ");
    Serial.println(humidityValue);
  }
}
